export const narrations = {"ha-noi":{"name":"Hà Nội","voice":"Linh","chapters":[{"id":"gioi-thieu","title":"Giới thiệu","text":"Xin chào bạn, mình là người đồng hành trong hành trình khám phá Hà Nội cùng Atlas Việt. Những cảnh ba trăm sáu mươi độ ở đây đưa chúng ta đến Hồ Hoàn Kiếm và các góc nhìn trên cao của khu vực trung tâm. Bạn hãy thử nhìn quanh, tìm mặt hồ, những mái nhà và đường phố. Từ không gian này, chúng ta sẽ mở rộng câu chuyện đến phố cổ, Hoàng thành Thăng Long, Văn Miếu và các bảo tàng. Hà Nội có nhiều lớp di sản và nhịp sống khác nhau. Bạn có thể chọn nghe về địa lý, lịch sử hoặc văn hóa trong lúc tiếp tục khám phá từng cảnh.","sources":[{"id":"S03","title":"Hanoi: six heritage sites","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/hanoi-six-heritage-sites","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cho tổng quan di tích, mốc Văn Miếu, Quốc Tử Giám và phố cổ. Loại chi tiết truyền thuyết và niên đại chưa đối chiếu thêm."},{"id":"S05","title":"11 must-see attractions in Ha Noi","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/11-must-see-attractions-ha-noi","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Bài có chi tiết cần biên tập: nhầm vua xây chùa Một Cột, nhầm nhân vật truyền thuyết trả gươm; cách gọi 54 ethnic minorities không chính xác; giá và giờ không có mốc rõ. Đã loại các chi tiết này, chỉ lấy mô tả địa danh có căn cứ."},{"id":"S07","title":"Thư ngỏ – Hoàng thành Thăng Long","publisher":"Trung tâm Bảo tồn di sản Thăng Long – Hà Nội","url":"https://hoangthanhthanglong.vn/thu-ngo/","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn quản lý nêu khai quật khảo cổ năm 2002 và UNESCO năm 2010; dùng đối chiếu lịch sử và di sản."},{"id":"S04","title":"3 walking tours of Hanoi","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/3-walking-tours-hanoi","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cho địa danh và tên món ăn; không lấy mô tả nguyên liệu phở cuốn trong bài. Tuyến đi bộ không được coi là hướng dẫn an toàn hay lịch hoạt động hiện hành."}],"src":"assets/audio/narration/ha-noi/gioi-thieu.mp3","duration":35.47,"script_sha256":"6f0c08e852b807a4d5806a8c7a88454af6043ec695aece910bda5067c007cf65"},{"id":"dia-ly","title":"Địa lý & cảnh quan","text":"Hồ nước là một cách thú vị để đọc không gian Hà Nội. Hồ Hoàn Kiếm nằm trong khu vực trung tâm, gắn với đền Ngọc Sơn, cầu Thê Húc và phố cổ lân cận. Khi nhìn từ trên cao, bạn có thể quan sát mặt hồ trong mối liên hệ với những tuyến phố bao quanh. Câu chuyện địa lý đô thị còn có sông Hồng, cầu Long Biên và khu vực Trúc Bạch. Những địa điểm ấy gợi mở nhiều tuyến đi bộ và góc nhìn khác nhau về thành phố. Tour hiện tại tập trung vào trung tâm Hà Nội; không phải mọi địa danh được nhắc đến đều có cảnh riêng trong trình xem.","sources":[{"id":"S04","title":"3 walking tours of Hanoi","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/3-walking-tours-hanoi","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cho địa danh và tên món ăn; không lấy mô tả nguyên liệu phở cuốn trong bài. Tuyến đi bộ không được coi là hướng dẫn an toàn hay lịch hoạt động hiện hành."},{"id":"S05","title":"11 must-see attractions in Ha Noi","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/11-must-see-attractions-ha-noi","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Bài có chi tiết cần biên tập: nhầm vua xây chùa Một Cột, nhầm nhân vật truyền thuyết trả gươm; cách gọi 54 ethnic minorities không chính xác; giá và giờ không có mốc rõ. Đã loại các chi tiết này, chỉ lấy mô tả địa danh có căn cứ."}],"src":"assets/audio/narration/ha-noi/dia-ly.mp3","duration":34.18,"script_sha256":"3471f060b8fe864be6ee612d94c8e0115240b811eb31be90dd612aaaf42be7ed"},{"id":"lich-su","title":"Lịch sử & di sản","text":"Hành trình lịch sử Hà Nội có thể bắt đầu từ Hoàng thành Thăng Long. Di tích lưu giữ nhiều lớp dấu tích qua các triều đại và được UNESCO ghi danh vào năm hai nghìn không trăm mười. Một điểm dừng khác là Văn Miếu, với mốc xây dựng năm một nghìn không trăm bảy mươi. Quốc Tử Giám có mốc năm một nghìn không trăm bảy mươi sáu. Những dấu mốc này giúp chúng ta tìm hiểu truyền thống giáo dục và lịch sử của kinh đô. Khi quan sát cảnh thành phố hôm nay, bạn có thể hình dung một hành trình tiếp theo qua các di tích để tìm hiểu sâu hơn về những lớp ký ức ấy.","sources":[{"id":"S03","title":"Hanoi: six heritage sites","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/hanoi-six-heritage-sites","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cho tổng quan di tích, mốc Văn Miếu, Quốc Tử Giám và phố cổ. Loại chi tiết truyền thuyết và niên đại chưa đối chiếu thêm."},{"id":"S07","title":"Thư ngỏ – Hoàng thành Thăng Long","publisher":"Trung tâm Bảo tồn di sản Thăng Long – Hà Nội","url":"https://hoangthanhthanglong.vn/thu-ngo/","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn quản lý nêu khai quật khảo cổ năm 2002 và UNESCO năm 2010; dùng đối chiếu lịch sử và di sản."}],"src":"assets/audio/narration/ha-noi/lich-su.mp3","duration":35.69,"script_sha256":"dc34a3f6b2faa0e59d91466274cac694c1e5e34c0a375d2f79bc6c67ea2f329a"},{"id":"van-hoa","title":"Văn hóa & ẩm thực","text":"Bạn có nhận ra những tên phố bắt đầu bằng chữ Hàng? Hàng Bạc, Hàng Mã, Hàng Đường gợi lại hoạt động nghề và buôn bán của phố cổ. Tên phố trở thành một lối vào câu chuyện văn hóa đô thị. Nếu muốn khám phá đời sống của các cộng đồng dân tộc trên cả nước, Bảo tàng Dân tộc học Việt Nam là một điểm dừng để tìm hiểu. Còn trong hành trình ẩm thực Hà Nội, phở và cà phê trứng là những gợi ý quen thuộc; phở cuốn và phở chiên phồng cũng xuất hiện trong các tuyến trải nghiệm được giới thiệu. Hãy xem đây là những gợi mở để tiếp tục khám phá theo sở thích của bạn.","sources":[{"id":"S03","title":"Hanoi: six heritage sites","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/hanoi-six-heritage-sites","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cho tổng quan di tích, mốc Văn Miếu, Quốc Tử Giám và phố cổ. Loại chi tiết truyền thuyết và niên đại chưa đối chiếu thêm."},{"id":"S05","title":"11 must-see attractions in Ha Noi","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/11-must-see-attractions-ha-noi","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Bài có chi tiết cần biên tập: nhầm vua xây chùa Một Cột, nhầm nhân vật truyền thuyết trả gươm; cách gọi 54 ethnic minorities không chính xác; giá và giờ không có mốc rõ. Đã loại các chi tiết này, chỉ lấy mô tả địa danh có căn cứ."},{"id":"S04","title":"3 walking tours of Hanoi","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/3-walking-tours-hanoi","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cho địa danh và tên món ăn; không lấy mô tả nguyên liệu phở cuốn trong bài. Tuyến đi bộ không được coi là hướng dẫn an toàn hay lịch hoạt động hiện hành."}],"src":"assets/audio/narration/ha-noi/van-hoa.mp3","duration":36.35,"script_sha256":"72671ba464982c1b809b3e076d1b0b5c4f88039494b2e9cb8e3efa0307268dc2"}]},"lao-cai":{"name":"Lào Cai","voice":"Linh","chapters":[{"id":"gioi-thieu","title":"Giới thiệu","text":"Xin chào bạn, chào mừng đến với Lào Cai cùng Atlas Việt. Trong tour này, chúng ta đang khám phá trung tâm Sa Pa: nhà thờ đá, quảng trường, hồ Sa Pa, Sun Plaza và khu chợ. Hãy thử chuyển từ góc nhìn trên cao xuống một cảnh gần mặt đất để quan sát phố và không gian sinh hoạt. Sổ tay Lào Cai còn giới thiệu Fansipan, Bắc Hà, Mù Cang Chải và hồ Thác Bà. Phạm vi tỉnh hiện nay gồm Lào Cai và Yên Bái trước sắp xếp năm hai nghìn không trăm hai mươi lăm. Những cảnh Sa Pa là điểm khởi đầu, chưa bao quát toàn bộ vùng đất ấy.","sources":[{"id":"S01","title":"Chi tiết 34 đơn vị hành chính cấp tỉnh","publisher":"Báo Điện tử Chính phủ","url":"https://xaydungchinhsach.chinhphu.vn/chi-tiet-34-don-vi-hanh-chinh-cap-tinh-tu-12-6-2025-119250612141845533.htm","displayed_date":"2026-10-05","accessed_on":"2026-10-06","status":"source_checked","note":"Dân số và diện tích Lào Cai là số liệu phục vụ sắp xếp năm 2025; không gọi là số liệu mới nhất năm 2026."},{"id":"S03","title":"Sapa","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/places-to-go/northern-vietnam/sapa","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cảnh quan, địa danh và chợ phiên; loại chiều cao Fansipan, thời gian cáp treo và thời gian di chuyển chưa đối chiếu. Mùa vụ và thời tiết là tham khảo, không phải dự báo."},{"id":"S04","title":"4 things you will love about Mu Cang Chai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/4-things-youll-love-about-mu-cang-chai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng địa danh tỉnh Yên Bái trước sắp xếp. Dùng mô tả cảnh quan và văn hóa; không dùng số giờ chạy xe hay lịch mùa vụ như cam kết hiện hành."},{"id":"S05","title":"Thac Ba Lake: the emerald of Yen Bai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/thac-ba-lake-emerald-yen-bai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng Yên Bái và huyện Yên Bình/Lục Yên trước sắp xếp. Đã ánh xạ phạm vi tỉnh qua S01; loại xếp hạng hồ, số đảo và diện tích chưa đối chiếu; không khuyến nghị món cá sống."}],"src":"assets/audio/narration/lao-cai/gioi-thieu.mp3","duration":37.22,"script_sha256":"4997c5733b32c97d89cde1b1191de79a885107ee3b44f024195784817f90b8ce"},{"id":"dia-ly","title":"Địa lý & cảnh quan","text":"Cảnh quan Lào Cai mở ra nhiều cách khám phá. Sa Pa gắn với núi, thung lũng và ruộng bậc thang. Mù Cang Chải nổi bật với những thửa ruộng trên sườn núi; Khau Phạ là con đèo trong khu vực Mù Cang Chải, Tú Lệ. Một không gian khác là hồ Thác Bà, hồ nhân tạo hình thành cùng công trình thủy điện Thác Bà. Trong tour hiện tại, bạn đang xem những cảnh ở trung tâm Sa Pa. Hãy dùng chúng làm điểm bắt đầu để tìm hiểu sự đa dạng giữa núi, ruộng bậc thang và cảnh quan hồ trong các hồ sơ của sổ tay.","sources":[{"id":"S03","title":"Sapa","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/places-to-go/northern-vietnam/sapa","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cảnh quan, địa danh và chợ phiên; loại chiều cao Fansipan, thời gian cáp treo và thời gian di chuyển chưa đối chiếu. Mùa vụ và thời tiết là tham khảo, không phải dự báo."},{"id":"S04","title":"4 things you will love about Mu Cang Chai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/4-things-youll-love-about-mu-cang-chai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng địa danh tỉnh Yên Bái trước sắp xếp. Dùng mô tả cảnh quan và văn hóa; không dùng số giờ chạy xe hay lịch mùa vụ như cam kết hiện hành."},{"id":"S05","title":"Thac Ba Lake: the emerald of Yen Bai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/thac-ba-lake-emerald-yen-bai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng Yên Bái và huyện Yên Bình/Lục Yên trước sắp xếp. Đã ánh xạ phạm vi tỉnh qua S01; loại xếp hạng hồ, số đảo và diện tích chưa đối chiếu; không khuyến nghị món cá sống."}],"src":"assets/audio/narration/lao-cai/dia-ly.mp3","duration":32.96,"script_sha256":"9ebe28a050454802bf1568432af27ea0087d7d5761068e2aa1313f4626aed39b"},{"id":"lich-su","title":"Lịch sử & di sản","text":"Phần lịch sử trong tư liệu Lào Cai của sổ tay được kể qua một vài lát cắt. Hồ Thác Bà gắn với công trình thủy điện, cho thấy mối liên hệ giữa hoạt động của con người và sự hình thành cảnh quan. Ruộng bậc thang lại gợi mở câu chuyện về sinh kế nông nghiệp trên sườn núi. Phạm vi hành chính của tỉnh thay đổi sau sắp xếp năm hai nghìn không trăm hai mươi lăm, gồm Lào Cai và Yên Bái trước đây. Vì vậy, khi đọc tài liệu cũ, chúng ta cần chú ý thời điểm của tên địa phương. Những lát cắt này giúp mở đầu việc tìm hiểu, nhưng chưa phải một niên biểu lịch sử đầy đủ của toàn tỉnh.","sources":[{"id":"S01","title":"Chi tiết 34 đơn vị hành chính cấp tỉnh","publisher":"Báo Điện tử Chính phủ","url":"https://xaydungchinhsach.chinhphu.vn/chi-tiet-34-don-vi-hanh-chinh-cap-tinh-tu-12-6-2025-119250612141845533.htm","displayed_date":"2026-10-05","accessed_on":"2026-10-06","status":"source_checked","note":"Dân số và diện tích Lào Cai là số liệu phục vụ sắp xếp năm 2025; không gọi là số liệu mới nhất năm 2026."},{"id":"S04","title":"4 things you will love about Mu Cang Chai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/4-things-youll-love-about-mu-cang-chai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng địa danh tỉnh Yên Bái trước sắp xếp. Dùng mô tả cảnh quan và văn hóa; không dùng số giờ chạy xe hay lịch mùa vụ như cam kết hiện hành."},{"id":"S05","title":"Thac Ba Lake: the emerald of Yen Bai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/thac-ba-lake-emerald-yen-bai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng Yên Bái và huyện Yên Bình/Lục Yên trước sắp xếp. Đã ánh xạ phạm vi tỉnh qua S01; loại xếp hạng hồ, số đảo và diện tích chưa đối chiếu; không khuyến nghị món cá sống."}],"src":"assets/audio/narration/lao-cai/lich-su.mp3","duration":37.44,"script_sha256":"ef0b98d40cfc026b3ff8491adc8d21ddbcf0f68e2ae8a364d6b8086271855f02"},{"id":"van-hoa","title":"Văn hóa & ẩm thực","text":"Đời sống cộng đồng là một phần quan trọng trong hành trình khám phá Lào Cai. Tại Mù Cang Chải, nghề dệt của người Mông là một chủ đề được giới thiệu trong tư liệu du lịch. Ở Ngòi Tu bên hồ Thác Bà, câu chuyện gắn với nhà sàn, nghề đan và sinh hoạt của cộng đồng Dao. Mỗi nét văn hóa cần được hiểu trong cộng đồng và không gian cụ thể. Trong trải nghiệm ẩm thực quanh hồ Thác Bà, tư liệu nhắc đến cơm lam và món gà nấu măng chua. Những câu chuyện đó gợi mở hành trình tiếp theo, bên cạnh các cảnh phố, hồ và chợ Sa Pa mà bạn đang xem.","sources":[{"id":"S04","title":"4 things you will love about Mu Cang Chai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/4-things-youll-love-about-mu-cang-chai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng địa danh tỉnh Yên Bái trước sắp xếp. Dùng mô tả cảnh quan và văn hóa; không dùng số giờ chạy xe hay lịch mùa vụ như cam kết hiện hành."},{"id":"S05","title":"Thac Ba Lake: the emerald of Yen Bai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/thac-ba-lake-emerald-yen-bai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng Yên Bái và huyện Yên Bình/Lục Yên trước sắp xếp. Đã ánh xạ phạm vi tỉnh qua S01; loại xếp hạng hồ, số đảo và diện tích chưa đối chiếu; không khuyến nghị món cá sống."}],"src":"assets/audio/narration/lao-cai/van-hoa.mp3","duration":35.78,"script_sha256":"0fe4b821b4a55e2a472d9af0931b6838b3f755e4e2d0a11555b122b05a7d74d9"}]},"ninh-binh":{"name":"Ninh Bình","voice":"Linh","chapters":[{"id":"gioi-thieu","title":"Giới thiệu","text":"Xin chào bạn, chào mừng đến với Ninh Bình cùng Atlas Việt. Trong chuyến tham quan này, mình sẽ đồng hành cùng bạn qua những ngọn núi đá vôi, dòng sông và dấu tích cố đô. Bạn có thể bắt đầu từ Hang Múa, nhìn xuống Tam Cốc, rồi chuyển sang Tràng An và Bái Đính. Mỗi góc nhìn kể một phần câu chuyện của vùng đất. Hãy kéo nhẹ trên ảnh để nhìn quanh, chọn cảnh bạn yêu thích và nghe từng phần thuyết minh. Những điểm đến này là một phần của Ninh Bình; chúng không đại diện cho toàn bộ tỉnh hiện nay.","sources":[{"id":"S01","title":"Chi tiết 34 đơn vị hành chính cấp tỉnh","publisher":"Báo Điện tử Chính phủ","url":"https://xaydungchinhsach.chinhphu.vn/chi-tiet-34-don-vi-hanh-chinh-cap-tinh-tu-12-6-2025-119250612141845533.htm","displayed_date":"2026-10-05","accessed_on":"2026-10-06","status":"source_checked","note":"Bài dẫn Nghị quyết 202/2025/QH15. Số liệu diện tích và dân số là số liệu phục vụ sắp xếp năm 2025."},{"id":"S03","title":"Ninh Bình","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/vi/places-to-go/northern-vietnam/ninh-binh","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Trang ghi bản dịch được AI tạo. Chỉ lấy nội dung tổng quát; không dùng các kỷ lục, mùa vụ hay lịch vận chuyển như thông tin hiện hành chưa đối chiếu."},{"id":"S04","title":"Quần thể Danh thắng Tràng An – Bảo tàng địa chất ngoài trời","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3021","displayed_date":"2025-03-27","accessed_on":"2026-10-06","status":"source_checked","note":"Ngày trang hiển thị không bảo đảm mọi chi tiết nội dung vẫn nguyên bản tại ngày đó. Không lấy diện tích tổng quần thể làm diện tích vùng lõi UNESCO."},{"id":"S05","title":"Cố đô Hoa Lư","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3020","displayed_date":"2025-03-27","accessed_on":"2026-10-06","status":"source_checked","note":"Bài trộn địa chỉ mới trong phần đầu và địa chỉ cũ ở cuối. Giá vé cần xác nhận lại."},{"id":"S06","title":"Khám phá vẻ đẹp non nước hữu tình tại Khu du lịch Tam Cốc – Bích Động","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3116","displayed_date":"2025-06-26","accessed_on":"2026-10-06","status":"source_checked","note":"Thời lượng thuyền và mùa lúa là mô tả tham khảo; điều kiện thực tế có thể thay đổi."},{"id":"S07","title":"Vườn quốc gia Cúc Phương","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3018","displayed_date":"2025-03-27","accessed_on":"2026-10-06","status":"source_checked","note":"Nội dung hiện đọc nêu Ninh Bình, Phú Thọ, Thanh Hóa; địa chỉ cuối bài khác website vườn. Không tự suy ra cổng vào từ địa chỉ này."},{"id":"S10","title":"Hang Múa – kỳ quan thiên nhiên hùng vĩ của Ninh Bình","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3007","displayed_date":"2025-03-24","accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn ghi phường Hoa Lư; chưa xác nhận lại địa chỉ. Câu chuyện nguồn gốc tên gọi được ghi là câu chuyện dân gian."},{"id":"S16","title":"Website Vườn quốc gia Cúc Phương","publisher":"Vườn quốc gia Cúc Phương","url":"https://vuonquocgiacucphuong.vn/vi/","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Đã đọc trang chủ. Có thông báo quy định phương tiện vào vùng lõi áp dụng từ 1/9/2026; chưa đọc đầy đủ quy định, không tự diễn giải điều kiện."}],"src":"assets/audio/narration/ninh-binh/gioi-thieu.mp3","duration":32.41,"script_sha256":"11b1e441ced393a56fcba3bf4964e5e6b81fbfcfcf8e29456f5b37e4c1a823c4"},{"id":"dia-ly","title":"Địa lý & cảnh quan","text":"Bạn hãy để ý những ngọn núi đá vôi và khoảng nước nằm giữa các thung lũng. Đó là nét cảnh quan nổi bật của khu vực Tràng An và Tam Cốc. Tại Tam Cốc, sông Ngô Đồng đi qua ba hang và những cánh đồng, tạo nên hành trình gắn kết sông nước với núi đá. Ninh Bình còn có những không gian thiên nhiên khác. Cúc Phương mở ra câu chuyện về hệ sinh thái rừng, còn vùng Kim Sơn gắn với bãi bồi ven biển và nghề cói. Khi đổi góc nhìn, bạn có thể quan sát cách núi, nước và hoạt động của con người cùng tạo nên cảnh quan.","sources":[{"id":"S04","title":"Quần thể Danh thắng Tràng An – Bảo tàng địa chất ngoài trời","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3021","displayed_date":"2025-03-27","accessed_on":"2026-10-06","status":"source_checked","note":"Ngày trang hiển thị không bảo đảm mọi chi tiết nội dung vẫn nguyên bản tại ngày đó. Không lấy diện tích tổng quần thể làm diện tích vùng lõi UNESCO."},{"id":"S06","title":"Khám phá vẻ đẹp non nước hữu tình tại Khu du lịch Tam Cốc – Bích Động","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3116","displayed_date":"2025-06-26","accessed_on":"2026-10-06","status":"source_checked","note":"Thời lượng thuyền và mùa lúa là mô tả tham khảo; điều kiện thực tế có thể thay đổi."},{"id":"S07","title":"Vườn quốc gia Cúc Phương","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3018","displayed_date":"2025-03-27","accessed_on":"2026-10-06","status":"source_checked","note":"Nội dung hiện đọc nêu Ninh Bình, Phú Thọ, Thanh Hóa; địa chỉ cuối bài khác website vườn. Không tự suy ra cổng vào từ địa chỉ này."},{"id":"S13","title":"Nghề cói Kim Sơn: Làng nghề truyền thống bên bãi bồi ven biển","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3663","displayed_date":"2026-07-28","accessed_on":"2026-10-06","status":"source_checked","note":"Kim Sơn ở đây là vùng văn hóa/nghề, không gán mọi cơ sở nghề vào xã Kim Sơn hiện hành."}],"src":"assets/audio/narration/ninh-binh/dia-ly.mp3","duration":33.92,"script_sha256":"27302da452ac043392d6909a76ec256c1cfafd3108b9150c779c081d34ed240d"},{"id":"lich-su","title":"Lịch sử & di sản","text":"Để tìm hiểu lịch sử Ninh Bình, chúng ta hãy hướng về Hoa Lư. Năm chín trăm sáu mươi tám, Đinh Bộ Lĩnh lên ngôi, mở ra một dấu mốc quan trọng trong lịch sử đất nước. Hoa Lư gắn với các triều Đinh, Tiền Lê và đầu thời Lý. Đến năm một nghìn không trăm mười, Lý Thái Tổ dời đô về Thăng Long. Ngày nay, đền thờ vua Đinh Tiên Hoàng và vua Lê Đại Hành là những điểm dừng để tìm hiểu ký ức lịch sử của vùng đất. Cảnh quan cố đô vì thế có thể được khám phá bằng cả đôi mắt và những câu chuyện của quá khứ.","sources":[{"id":"S05","title":"Cố đô Hoa Lư","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3020","displayed_date":"2025-03-27","accessed_on":"2026-10-06","status":"source_checked","note":"Bài trộn địa chỉ mới trong phần đầu và địa chỉ cũ ở cuối. Giá vé cần xác nhận lại."}],"src":"assets/audio/narration/ninh-binh/lich-su.mp3","duration":33.58,"script_sha256":"bed08aa61e33740a616af249f26309821f2a787b67345919845ef223b013df9b"},{"id":"van-hoa","title":"Văn hóa & ẩm thực","text":"Văn hóa Ninh Bình hiện diện trong lễ hội, nghề thủ công và bữa ăn địa phương. Lễ hội Hoa Lư tưởng nhớ các vị vua và tiền nhân, với những nghi thức như rước nước, rước kiệu và dâng hương. Nghề thêu ren Văn Lâm và nghề cói Kim Sơn cho thấy kỹ năng được gìn giữ qua nhiều thế hệ. Bái Đính và Phát Diệm gợi mở những cách tiếp cận khác nhau về kiến trúc tôn giáo. Còn trong câu chuyện ẩm thực, bạn có thể tìm hiểu cơm cháy, thịt dê, mắm tép Gia Viễn và nem chua Yên Mạc. Mỗi tên gọi là một gợi ý để khám phá sâu hơn về đời sống địa phương.","sources":[{"id":"S08","title":"Chùa Bái Đính","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3015","displayed_date":"2025-03-26","accessed_on":"2026-10-06","status":"source_checked","note":"Không đưa các tuyên bố kỷ lục vào dữ liệu đã duyệt khi chưa đọc xác nhận riêng."},{"id":"S09","title":"Nhà thờ đá Phát Diệm","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3014","displayed_date":"2025-03-26","accessed_on":"2026-10-06","status":"source_checked","note":"Dùng mô tả kiến trúc và khoảng thời gian xây dựng theo bài; xã Phát Diệm đối chiếu S02."},{"id":"S11","title":"Lễ hội Hoa Lư – Nơi lưu giữ nét đẹp truyền thống nghìn năm","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3359","displayed_date":"2025-09-24","accessed_on":"2026-10-06","status":"source_checked","note":"Lịch thường niên không thay thế thông báo tổ chức của từng năm."},{"id":"S12","title":"Làng nghề thêu ren Văn Lâm tinh hoa thủ công Ninh Bình","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3684","displayed_date":"2026-08-21","accessed_on":"2026-10-06","status":"source_checked","note":"Giới thiệu nghề; chưa xác nhận cơ sở nào có tour trải nghiệm đang mở."},{"id":"S13","title":"Nghề cói Kim Sơn: Làng nghề truyền thống bên bãi bồi ven biển","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3663","displayed_date":"2026-07-28","accessed_on":"2026-10-06","status":"source_checked","note":"Kim Sơn ở đây là vùng văn hóa/nghề, không gán mọi cơ sở nghề vào xã Kim Sơn hiện hành."},{"id":"S14","title":"Mắm tép Gia Viễn, đậm đà hương vị quê hương","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3719","displayed_date":"2026-09-14","accessed_on":"2026-10-06","status":"source_checked","note":"Thông tin văn hóa ẩm thực, không phải hướng dẫn bảo đảm an toàn thực phẩm."},{"id":"S15","title":"Nem chua Yên Mạc – Tinh hoa ẩm thực truyền thống của Ninh Bình","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3718","displayed_date":"2026-09-14","accessed_on":"2026-10-06","status":"source_checked","note":"Bài cũng nhắc cơm cháy và thịt dê là đặc sản Ninh Bình; chưa xác minh giá hoặc cửa hàng."}],"src":"assets/audio/narration/ninh-binh/van-hoa.mp3","duration":35.89,"script_sha256":"a0e7e1fa480b7080895d90cf054fc27c043981d74246d471d5f989ecb52d382e"}]},"quang-ninh":{"name":"Quảng Ninh","voice":"Linh","chapters":[{"id":"gioi-thieu","title":"Giới thiệu","text":"Chào mừng bạn đến với hành trình khám phá Quảng Ninh cùng Atlas Việt. Tour ba trăm sáu mươi độ hiện đưa chúng ta quanh Vịnh Hạ Long, qua đảo đá, hang động, làng chài và những góc nhìn trên mặt vịnh. Hãy chọn một cảnh, kéo để nhìn quanh và cảm nhận sự thay đổi của cảnh quan. Câu chuyện Quảng Ninh còn mở rộng đến Cô Tô, Quan Lạn, Yên Tử và Bảo tàng, Thư viện Quảng Ninh. Các địa điểm đó được giới thiệu trong lời thuyết minh, nhưng chưa có đầy đủ cảnh riêng trong tour này. Mình sẽ đồng hành cùng bạn tìm hiểu từng chủ đề trong lúc ngắm cảnh.","sources":[{"id":"S02","title":"Ha Long","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/places-to-go/northern-vietnam/ha-long","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Chỉ lấy mô tả cảnh quan và trải nghiệm tổng quát. Nội dung có nhắc điểm ngoài Quảng Ninh; đã loại khỏi hồ sơ. Không lấy lịch hoặc thời gian vận chuyển làm thông tin hiện hành."},{"id":"S05","title":"Khu di tích lịch sử và danh lam thắng cảnh Yên Tử","publisher":"Cổng thông tin điện tử Quảng Ninh","url":"https://www.quangninh.gov.vn/Trang/ChiTietBVGioiThieu.aspx?bvid=530","displayed_date":"2025-07-14","accessed_on":"2026-10-06","status":"source_checked","note":"Bài nêu địa giới phường sau sắp xếp và sự kiện UNESCO ngày 12/07/2025. Chỉ lấy phần di tích Quảng Ninh, không mở rộng hồ sơ sang Bắc Ninh hoặc Hải Phòng."},{"id":"S06","title":"Bảo tàng – Thư viện thành phố","publisher":"Sở Văn hóa, Thể thao và Du lịch Quảng Ninh","url":"https://www.quangninh.gov.vn/so/sovanhoathethao/trang/chitietbvgioithieu.aspx?bvid=84","displayed_date":"2026-09-04","accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn về chức năng và nhiệm vụ đơn vị, không phải hướng dẫn trưng bày hoặc giá vé. Không nhập thông tin cá nhân cán bộ vào database du lịch."},{"id":"S03","title":"Co To Island: pristine beauty of Northeast Vietnam","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://www.vietnam.travel/vi/things-to-do/co-island-pristine-beauty-northeast-vietnam","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Trang tiếng Việt ghi bản dịch do AI tạo. Chỉ lấy mô tả địa danh tổng quát; loại số liệu, niên đại hải đăng và quy định hạn chế nhựa chưa đối chiếu."},{"id":"S04","title":"Discovering the beauty of Quan Lan Island","publisher":"Cục Du lịch Quốc gia Việt Nam – TITC","url":"https://vietnamtourism.gov.vn/en/post/9785","displayed_date":"2015-11-09","accessed_on":"2026-10-06","status":"source_checked","note":"Bài năm 2015 dùng địa danh huyện Vân Đồn trước sắp xếp. Không nhập số lượng phòng, cơ sở lưu trú, lịch tàu, giá hay thời gian chạy tàu như hiện hành."}],"src":"assets/audio/narration/quang-ninh/gioi-thieu.mp3","duration":35.42,"script_sha256":"f46104f87a089a51df19f701254bc163ba86b7d86d1698b7b7c1c7766d0b477d"},{"id":"dia-ly","title":"Địa lý & cảnh quan","text":"Điểm nổi bật của Hạ Long là những khối núi đá vôi giữa biển. Trong tour, bạn có thể đổi từ góc nhìn trên cao xuống các cảnh gần mặt nước để quan sát hình dáng đảo đá và khoảng biển giữa chúng. Quảng Ninh còn có những không gian khác: Quan Lạn nằm trong vịnh Bái Tử Long; Cô Tô gắn với bãi biển, bờ đá và đảo Thanh Lân. Yên Tử lại mở ra cảnh quan núi rừng. Sự khác biệt giữa biển đảo và núi giúp bạn lựa chọn các chủ đề khám phá. Những cảnh hiện có là một lát cắt về Vịnh Hạ Long, không phải toàn cảnh mọi điểm đến của Quảng Ninh.","sources":[{"id":"S02","title":"Ha Long","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/places-to-go/northern-vietnam/ha-long","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Chỉ lấy mô tả cảnh quan và trải nghiệm tổng quát. Nội dung có nhắc điểm ngoài Quảng Ninh; đã loại khỏi hồ sơ. Không lấy lịch hoặc thời gian vận chuyển làm thông tin hiện hành."},{"id":"S03","title":"Co To Island: pristine beauty of Northeast Vietnam","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://www.vietnam.travel/vi/things-to-do/co-island-pristine-beauty-northeast-vietnam","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Trang tiếng Việt ghi bản dịch do AI tạo. Chỉ lấy mô tả địa danh tổng quát; loại số liệu, niên đại hải đăng và quy định hạn chế nhựa chưa đối chiếu."},{"id":"S04","title":"Discovering the beauty of Quan Lan Island","publisher":"Cục Du lịch Quốc gia Việt Nam – TITC","url":"https://vietnamtourism.gov.vn/en/post/9785","displayed_date":"2015-11-09","accessed_on":"2026-10-06","status":"source_checked","note":"Bài năm 2015 dùng địa danh huyện Vân Đồn trước sắp xếp. Không nhập số lượng phòng, cơ sở lưu trú, lịch tàu, giá hay thời gian chạy tàu như hiện hành."},{"id":"S05","title":"Khu di tích lịch sử và danh lam thắng cảnh Yên Tử","publisher":"Cổng thông tin điện tử Quảng Ninh","url":"https://www.quangninh.gov.vn/Trang/ChiTietBVGioiThieu.aspx?bvid=530","displayed_date":"2025-07-14","accessed_on":"2026-10-06","status":"source_checked","note":"Bài nêu địa giới phường sau sắp xếp và sự kiện UNESCO ngày 12/07/2025. Chỉ lấy phần di tích Quảng Ninh, không mở rộng hồ sơ sang Bắc Ninh hoặc Hải Phòng."}],"src":"assets/audio/narration/quang-ninh/dia-ly.mp3","duration":35.32,"script_sha256":"86013e1e62280b8bbd1e62c87c61d8bc5e8b78e17a764f61e31c4636bc4e8692"},{"id":"lich-su","title":"Lịch sử & di sản","text":"Khi tìm hiểu lịch sử và di sản Quảng Ninh, Yên Tử là một điểm dừng đáng chú ý. Nơi đây gắn với Trần Nhân Tông và Thiền phái Trúc Lâm. Chùa, am và tháp tạo thành không gian kiến trúc giữa núi rừng, giúp chúng ta tìm hiểu câu chuyện Phật giáo và ký ức lịch sử. Khu di tích được xếp hạng quốc gia đặc biệt vào năm hai nghìn không trăm mười hai. Đây là một dấu mốc về di tích Yên Tử. Trong khi ngắm Vịnh Hạ Long, bạn có thể ghi nhớ chủ đề này cho một hành trình khác, kết nối cảnh quan biển với việc tìm hiểu di sản trên núi.","sources":[{"id":"S05","title":"Khu di tích lịch sử và danh lam thắng cảnh Yên Tử","publisher":"Cổng thông tin điện tử Quảng Ninh","url":"https://www.quangninh.gov.vn/Trang/ChiTietBVGioiThieu.aspx?bvid=530","displayed_date":"2025-07-14","accessed_on":"2026-10-06","status":"source_checked","note":"Bài nêu địa giới phường sau sắp xếp và sự kiện UNESCO ngày 12/07/2025. Chỉ lấy phần di tích Quảng Ninh, không mở rộng hồ sơ sang Bắc Ninh hoặc Hải Phòng."}],"src":"assets/audio/narration/quang-ninh/lich-su.mp3","duration":34.58,"script_sha256":"03fef9c4030a2a71f6372466ed4ae98162a1eaf8e7f23aed6f48d936f4bb88da"},{"id":"van-hoa","title":"Văn hóa & ẩm thực","text":"Văn hóa Quảng Ninh có thể được khám phá qua nhiều không gian. Tại Yên Tử, kiến trúc chùa, am và tháp gắn với sinh hoạt Phật giáo. Quan Lạn có cụm đình, đền, chùa, cho thấy chuyến đi biển đảo cũng là cơ hội tìm hiểu di sản văn hóa. Bảo tàng, Thư viện Quảng Ninh góp phần lưu giữ và giới thiệu câu chuyện địa phương. Ẩm thực lại mở một góc nhìn về đời sống gắn với biển: các bài giới thiệu Cô Tô nhắc đến mực, hàu, bề bề và sá sùng. Đây là những nguyên liệu được giới thiệu trong trải nghiệm du lịch, không phải những món chỉ có ở Quảng Ninh.","sources":[{"id":"S04","title":"Discovering the beauty of Quan Lan Island","publisher":"Cục Du lịch Quốc gia Việt Nam – TITC","url":"https://vietnamtourism.gov.vn/en/post/9785","displayed_date":"2015-11-09","accessed_on":"2026-10-06","status":"source_checked","note":"Bài năm 2015 dùng địa danh huyện Vân Đồn trước sắp xếp. Không nhập số lượng phòng, cơ sở lưu trú, lịch tàu, giá hay thời gian chạy tàu như hiện hành."},{"id":"S05","title":"Khu di tích lịch sử và danh lam thắng cảnh Yên Tử","publisher":"Cổng thông tin điện tử Quảng Ninh","url":"https://www.quangninh.gov.vn/Trang/ChiTietBVGioiThieu.aspx?bvid=530","displayed_date":"2025-07-14","accessed_on":"2026-10-06","status":"source_checked","note":"Bài nêu địa giới phường sau sắp xếp và sự kiện UNESCO ngày 12/07/2025. Chỉ lấy phần di tích Quảng Ninh, không mở rộng hồ sơ sang Bắc Ninh hoặc Hải Phòng."},{"id":"S06","title":"Bảo tàng – Thư viện thành phố","publisher":"Sở Văn hóa, Thể thao và Du lịch Quảng Ninh","url":"https://www.quangninh.gov.vn/so/sovanhoathethao/trang/chitietbvgioithieu.aspx?bvid=84","displayed_date":"2026-09-04","accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn về chức năng và nhiệm vụ đơn vị, không phải hướng dẫn trưng bày hoặc giá vé. Không nhập thông tin cá nhân cán bộ vào database du lịch."},{"id":"S03","title":"Co To Island: pristine beauty of Northeast Vietnam","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://www.vietnam.travel/vi/things-to-do/co-island-pristine-beauty-northeast-vietnam","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Trang tiếng Việt ghi bản dịch do AI tạo. Chỉ lấy mô tả địa danh tổng quát; loại số liệu, niên đại hải đăng và quy định hạn chế nhựa chưa đối chiếu."}],"src":"assets/audio/narration/quang-ninh/van-hoa.mp3","duration":36.93,"script_sha256":"714d363a10facbd02ad6680013a3e51d5f650380715b416e2d099c6ee64c987f"}]}};
